Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -18,9 +18,9 @@
 (()=>{'use strict';
 const TYPES={mine:{name:'Mina de ouro',icon:'⛏️',cost:65,desc:'+30 ouro por dia',income:30,power:0,cap:0},trap:{name:'Armadilha',icon:'🪤',cost:55,desc:'Enfraquece invasores',income:0,power:0,trap:8},lair:{name:'Covil de goblins',icon:'👺',cost:80,desc:'+2 capacidade da horda',income:0,power:0,cap:2},barracks:{name:'Quartel sombrio',icon:'⚔️',cost:95,desc:'+8 poder de combate',income:0,power:8},crystal:{name:'Veio arcano',icon:'💠',cost:110,desc:'+1 cristal a cada 3 dias',income:0,power:0,crystal:1}};
 const fresh=()=>({gold:160,crystals:0,essence:0,day:1,minions:3,core:100,rooms:{12:'core'},log:[],ended:false});let state;try{state=JSON.parse(localStorage.dungeonEmpireSave)||fresh()}catch{state=fresh()};if(!state.rooms)state=fresh();let selected=null,toastTimer;
 const $=id=>document.getElementById(id);function save(){localStorage.setItem('dungeonEmpireSave',JSON.stringify(state))}function roomType(pos){return state.rooms[pos]}function capacity(){return 5+Object.values(state.rooms).filter(x=>x==='lair').length*2}function power(){return state.minions*4+Object.values(state.rooms).filter(x=>x==='barracks').length*8}function addLog(text,kind=''){state.log.unshift({day:state.day,text,kind});state.log=state.log.slice(0,18)}function notify(text){const t=$('toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
-function render(){ $('gold').textContent=state.gold;$('crystals').textContent=state.crystals;$('essence').textContent=state.essence;$('day').textContent=state.day;$('minions').textContent=state.minions;$('capacity').textContent=capacity();$('power').textContent='⚡ '+power();$('power-meter').style.width=Math.min(100,power()*2)+'%';const occupied=Object.keys(state.rooms).length-1;$('room-count').textContent=`${occupied} / 9 salas`;
+function render(){ $('gold').textContent=state.gold;$('crystals').textContent=state.crystals;$('essence').textContent=state.essence;$('day').textContent=state.day;$('minions').textContent=state.minions;$('capacity').textContent=capacity();$('power').textContent='⚡ '+power();$('power-meter').style.width=Math.min(100,power()*2)+'%';$('core-text').textContent=state.core+'%';$('core-meter').style.width=state.core+'%';const occupied=Object.keys(state.rooms).length-1;$('room-count').textContent=`${occupied} / 9 salas`;
 const grid=$('grid');grid.innerHTML='';for(let i=0;i<25;i++){const div=document.createElement('button');div.className='tile';const type=roomType(i);if(type){div.classList.add(type==='core'?'core':'room');const def=type==='core'?{icon:'💜',name:'Núcleo'}:TYPES[type];div.innerHTML=`<span class="emoji">${def.icon}</span><span class="label">${def.name}</span>`;}else{const around=[i-1,i+1,i-5,i+5].some(n=>roomType(n));if(around&&occupied<9){div.classList.add('empty');div.innerHTML='<span class="plus">+</span>';div.onclick=()=>{selected=i;document.querySelectorAll('.tile').forEach(t=>t.style.outline='');div.style.outline='2px solid #e8b952';notify('Agora escolha uma sala para construir.')}}else{div.classList.add('locked');div.innerHTML='<span class="lock">🔒</span>'}}grid.appendChild(div)}
 const list=$('room-list');list.innerHTML='';Object.entries(TYPES).forEach(([key,r])=>{const card=document.createElement('div');card.className='room-card';card.innerHTML=`<div class="room-icon">${r.icon}</div><div class="room-info"><b>${r.name}</b><small>${r.desc}</small></div><button class="build-btn" ${state.gold<r.cost||occupied>=9?'disabled':''}>${r.cost} 🪙</button>`;card.querySelector('button').onclick=()=>build(key);list.appendChild(card)});
 $('recruit').disabled=state.gold<35||state.minions>=capacity()||state.ended;$('recruit').style.opacity=$('recruit').disabled?'.48':'1';$('log').innerHTML=state.log.map(e=>`<div class="event ${e.kind}"><time>DIA ${e.day}</time>${e.text}</div>`).join('');$('advance').disabled=state.ended;if(state.ended)$('overlay').classList.add('show');else $('overlay').classList.remove('show');}
 function build(type){if(selected===null){notify('Toque em um espaço vazio da masmorra primeiro.');return}const def=TYPES[type];if(state.gold<def.cost){notify('Ouro insuficiente!');return}if(Object.keys(state.rooms).length-1>=9){notify('Sua masmorra está cheia.');return}state.gold-=def.cost;state.rooms[selected]=type;selected=null;addLog(`${def.icon} ${def.name} construída.`,'good');save();render()}

